# The first object is a black camera with a lens; I will remember it for matching.
# Hold both arms clear for 20 steps to measure conveyor motion.
obs = get_observation()
hold = {k: v for k, v in obs['state'].items() if k.endswith('joint_state')}
for i in range(20):
    obs, reward, terminated, truncated, info = step(hold)
    if terminated or truncated:
        break
print(obs['state'])

